SELECT json_object('obs','heading','declined',CASE WHEN (SELECT b.block_id FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0) IS NULL THEN 1 ELSE 0 END,'value_kind','text','value',(SELECT b.text FROM headings h JOIN blocks b ON b.block_id=h.block_id WHERE h.doc_id=1 AND h.ord=0),'coord',NULL,'provenance',NULL,'exact',json_object('length',(SELECT source_len FROM documents WHERE doc_id=1),'sha256',(SELECT source_sha256 FROM documents WHERE doc_id=1)),'revision',NULL)